CREATE DATABASE IF NOT EXISTS pythonpro CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pythonpro;
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE student_profiles(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,student_id VARCHAR(64) NOT NULL UNIQUE,course VARCHAR(120) NOT NULL,year VARCHAR(20) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE user_states(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,data JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE lessons(id VARCHAR(64) PRIMARY KEY,title VARCHAR(255) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE questions(id VARCHAR(64) PRIMARY KEY,title VARCHAR(255) NOT NULL,topic VARCHAR(80) NOT NULL,difficulty VARCHAR(16) NOT NULL,question_type VARCHAR(40) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_question_filter(topic,difficulty,question_type));
CREATE TABLE quizzes(id VARCHAR(64) PRIMARY KEY,title VARCHAR(255) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coding_problems(id VARCHAR(64) PRIMARY KEY,title VARCHAR(255) NOT NULL,difficulty VARCHAR(16) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(difficulty));
CREATE TABLE projects(id VARCHAR(64) PRIMARY KEY,title VARCHAR(255) NOT NULL,difficulty VARCHAR(16) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(difficulty));
CREATE TABLE lesson_progress(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,lesson_id VARCHAR(64) NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,lesson_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(lesson_id) REFERENCES lessons(id));
CREATE TABLE question_attempts(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,question_id VARCHAR(64) NOT NULL,answer TEXT,correct BOOLEAN NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE quiz_attempts(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,quiz_id VARCHAR(64) NOT NULL,score INT NOT NULL,total INT NOT NULL,seconds INT NOT NULL DEFAULT 0,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE coding_submissions(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,problem_id VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,code MEDIUMTEXT NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE project_progress(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,project_id VARCHAR(64) NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,project_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE bookmarks(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,kind VARCHAR(30) NOT NULL,item_id VARCHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(user_id,kind,item_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE achievements(id VARCHAR(64) PRIMARY KEY,title VARCHAR(255) NOT NULL,payload JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student_achievements(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,achievement_id VARCHAR(64) NOT NULL,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,achievement_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,message TEXT NOT NULL,`read` BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
